library_heal_metadata_tooltip: "ينسخ ملفات ‎icon0.png / param.json / snd0.at9 المفقودة من مجلد ‎sce_sys/‎ الخاص بهذه اللعبة إلى ‎/user/appmeta/<title_id>/‎. العملية عديمة التأثير عند التكرار — تُترك الملفات الموجودة كما هي. استخدمها عندما تكون بطاقة الشاشة الرئيسية فارغة أو تكون موسيقى القائمة مفقودة.",
