library_mount_modal_cross_volume: "تنبيه: الصورة موجودة على {imageVolume} لكنك اخترت {volume}. ترفض بعض إصدارات برامج PS5 الثابتة عملية nmount عبر الوحدات بالخطأ EPERM (لا تركّب النواة ملفًا من قرص داخل مسار على قرص آخر). إذا فشل التركيب، أعد المحاولة باستخدام {imageVolume} كوحدة تخزين.",
