library_mount_modal_usb_warn_body: "ينتمي ‎/mnt/usb*‎ و‎/mnt/ext*‎ إلى فضاء أسماء التوصيل الساخن لـ USB في نواة PS5؛ وتركيب صورة هناك تحجبه سياسة النواة على معظم الإصدارات الثابتة. إذا فشل بالخطأ «Operation not permitted»، فانتقل إلى ‎/mnt/ps5upload (جذر التركيب الخاص بالحمولة) أو ‎/data — كلاهما يعمل دون ترقيعات للنواة.",
library_mount_modal_usb_warn_switch: "التبديل إلى ‎/mnt/ps5upload/",
