library_register_drm: "إضافة إلى الشاشة الرئيسية (تصحيح DRM)",
library_register_drm_tooltip: "مثل «إضافة إلى الشاشة الرئيسية»، لكنه يصحّح أولًا قيمة applicationDrmType في المصدر إلى \"standard\" — ويعدّل ملف المصدر. استخدمه فقط عندما تفشل الإضافة العادية بخطأ DRM.",
