saves_restore_confirm_body_v2: "أغلق اللعبة أولًا. اختر نسخة .zip احتياطية لهذه اللعبة أنشأها PS5 هذا وهذا المستخدم. تُنسخ حفظة PS5، ثم تُستبدل، وتُعاد إذا فشلت الاستعادة. لا تبقى تلك النسخة بعد ذلك إلا إذا عُيّن مجلد أو خادم نسخ احتياطي في النسخ الاحتياطي التلقائي.",
