err_uninstall_unavailable:
  "لا توفر البرامج الثابتة لجهاز PS5 هذا أي طريقة للمساعد لإلغاء التثبيت، وما زالت اللعبة مثبتة. احذفها من الإعدادات ← التخزين على PS5.",
