  "قبل جهاز PS5 إلغاء التثبيت، لكن {name} ما زالت على الجهاز. قد تستغرق إزالة لعبة كبيرة بضع دقائق: حدّث القائمة بعد قليل. وإذا بقيت فاحذفها من الإعدادات ← التخزين على PS5.",
err_unmount_permission:
  "تعذّر إلغاء التركيب: رفضت النواة العملية بالخطأ EACCES/EPERM. ربما فقد الـ payload صلاحيات الجذر — أعد تحميله من Connection → Send payload.",
err_not_enough_space: "لا توجد مساحة خالية كافية على هذا الكمبيوتر: يحتاج إلى {need}، والخالي {free}. حرّر بعض المساحة وحاول مجددًا.",
err_link_changed: "تغيّر الملف الموجود على هذا الرابط أثناء قراءته، فلا يمكن إكمال ما قُرئ حتى الآن به. ابدأ من جديد.",
err_pair_pending: "رفض PS5 الإقران (80108b03). على PS5 افتح الإعدادات › النظام › التشغيل عن بُعد وفعّل «تمكين التشغيل عن بُعد». إن كان باهتًا، فغالبًا لم يُفعَّل حساب مستخدم PS5 هذا: فعّله في الحسابات › المستخدمون. وإن ظل لا يعمل أو لا يبقى مفعّلًا: شغّل تسجيل الدخول دون اتصال في «إعداد «العب»» ثم أعد تشغيل PS5. بعد ذلك اضغط «إقران» مرة أخرى.",
err_unpack_no_space: "لا توجد مساحة كافية على هذا القرص للصورة بعد فك ضغطها. تحتاج إلى الحجم الكامل للصورة زائد 1 غيبيبايت.",
