volumes_pkg_copies_hint: "ما يفعله هذا الخيار: «الرفع والتثبيت» ينسخ ملف ‎.pkg إلى PS5 أولًا ثم يثبّت من تلك النسخة. هذا يحدد فقط القرص الذي يحتفظ بهذه النسخ. لا يغيّر مكان تثبيت الألعاب (يقرره PS5 في إعدادات التخزين لديه)، و«البث والتثبيت» لا يحتفظ بأي نسخة. إذا لم يكن القرص المختار متصلًا، تذهب النسخ إلى التخزين الداخلي.",
