"arcpkg.choose": "اختر أرشيفًا…",
"arcpkg.help": "لملف ‎.zip أو ‎.7z أو ‎.rar يحتوي على ملف ‎.pkg واحد أو أكثر داخل أي مجلد. تُفك الحزم فقط، مباشرة إلى PS5 (لا يُستخرج شيء على هذا الحاسوب)، ثم تُثبَّت واحدة تلو الأخرى: اللعبة الأساسية أولًا، ثم تحديثها، ثم المحتوى الإضافي. أرشيف RAR متعدد الأجزاء (‎.part1.rar، ‎.part2.rar…) مدعوم: اختر الجزء الأول وأبقِ البقية بجانبه. تُطلب كلمة المرور عندما يحتاجها RAR؛ أما ZIP و7z المحميان بكلمة مرور فغير مدعومين.",
"arcpkg.helpNoRar": "لملف ‎.zip أو ‎.7z يحوي ملف ‎.pkg واحدًا أو أكثر في أي مجلد. تُفك الحزم فقط، مباشرة إلى PS5 (لا يُفك شيء على هذا الجهاز)، ثم تُثبت واحدة تلو الأخرى: اللعبة الأساسية قبل تحديثها، ثم المحتوى الإضافي. الملفات المحمية بكلمة مرور غير مدعومة، وتحتاج ‎.rar إلى تطبيق سطح المكتب.",
