trace_what: "لصورة لعبة LZ4 تُحمَّل كما تُلعب اللعبة. نسخة قياس من ampr_emu تسجّل كل ملف تقرأه اللعبة أثناء اللعب؛ وملف تعريف مبني من تلك الجلسات يختار أحجام الكتل والتخطيط وأحجام الذاكرة المؤقتة لكل ملف بدل تخمين واحد للكل. يستخدمه Convert عند إنشاء صورة LZ4 لهذه اللعبة.",
