about_feat_cheats_title: "أكواد الغش",
about_feat_console_body: "وضع الراحة وإعادة التشغيل وإيقاف التشغيل والإيقاظ عبر الشبكة، إضافةً إلى العمليات الجارية ومنحنى المروحة ونظرة عامة على العتاد.",
about_feat_console_title: "التحكم بالجهاز",
about_feat_convert_body: "حوّل مجلد لعبة أو صورتها إلى حزمة قابلة للتثبيت، أو مجلدًا إلى صورة لعبة يركّبها ShadowMount+.",
about_feat_convert_title: "تحويل الألعاب",
about_feat_install_body: "حزم PS4 .pkg وحزم PS5 المزيفة (أساسية، تحديث، DLC) من هذا الكمبيوتر أو مشاركة NAS أو قرص USB أو رابط. إذا رفض PS5 طريقة ما، يعرض التطبيق طريقة أخرى.",
about_feat_install_title: "تثبيت الحزم",
about_feat_payloads_body: "أرسل ملفات ELF الخاصة بالحمولات إلى مُحمِّل الجهاز، من الكتالوج أو من ملفاتك، واحدًا تلو الآخر أو كقائمة تشغيل.",
about_feat_payloads_title: "الحمولات",
about_feat_saves_body: "انسخ الحفظ احتياطيًا تلقائيًا إلى مجلد أو خادم، واستعده، أو انسخه إلى مستخدم آخر أو جهاز PS5 آخر.",
about_feat_saves_title: "بيانات الحفظ",
activity_cancel_tooltip: "إلغاء هذه العملية",
activity_clear_shown_confirm_body: "يزيل الإدخالات المنتهية المعروضة هنا (المكتملة والفاشلة والمتوقفة). يُحتفظ بسجل الأجهزة الأخرى وبكل ما لا يزال قيد التشغيل. لحذف صف واحد، استخدم زر سلة المهملات الخاص به.",
activity_clear_shown_confirm_title: "مسح هذا السجل؟",
activity_view_history: "السجل",
"always_overwrite_hint_v2": "تخطَّ التأكيد عندما تحتوي وجهة الرفع على ملفات بالفعل. اتركه مطفأً لترى خيارات الاستبدال / الاستئناف / الإلغاء.",
audit_empty_v2: "لم يُسجَّل شيء بعد. تظهر هنا إجراءات الطاقة (الإيقاظ، وضع الراحة، إعادة التشغيل، إيقاف التشغيل) وعمليات الحذف وإلغاء التسجيل وإلغاء التثبيت والتثبيت عند تنفيذها.",
audit_log_description_v3: "سجلٌّ محفوظ في هذا التطبيق على هذا الكمبيوتر لإجراءات الطاقة وعمليات الحذف وإلغاء التسجيل وإلغاء التثبيت والتثبيت. يُحتفظ بأحدث 256 إدخالًا وتُحذف الأقدم تلقائيًا؛ لا يوجد زر مسح، لكن مسح بيانات التطبيق أو تخزين المتصفح يمحوه. تُعرض آخر 100 إدخال.",
autoloader_title_v2: "قائمة تشغيل عند الاتصال",
