backup_limit_depth: "تُتخطّى المجلدات التي تقع على عمق أكثر من {n} مستويات تحت المجلد الذي تختاره.",
backup_limit_flatten: "تُخزَّن الملفات باسم مسارها مع تحويل كل / إلى _، لذا قد ينتهي مساران مختلفان بالاسم نفسه (a/b_c و a_b/c) ويُحتفظ بواحد منهما فقط.",
backup_limit_keep: "يُحتفظ فقط بأحدث {n} لقطات لكل اسم؛ وإنشاء لقطة أخرى يحذف الأقدم.",
backup_subtitle_v3: "انسخ الملفات والمجلدات إلى لقطة محفوظة على PS5 نفسه، وأعدها لاحقًا. لا يُنسخ شيء إلى هذا الكمبيوتر. لبيانات حفظ الألعاب، استخدم «بيانات الحفظ».",
bandwidth_cap_clear: "إزالة الحد",
bandwidth_cap_on_hint_v2: "تُقيَّد جميع عمليات الرفع معًا بنحو {n} ميغابايت/ث، بدءًا من الرفع التالي. عيّن القيمة 0 لإزالة الحد.",
beta_features_hint_v2: "يضيف شاشات قيد التطوير إلى الشريط الجانبي عند وجودها. يمكن استخدامها لكنها ليست موثوقة بعد، وقد تتغير أو تُزال.",
bringup_desc_v2: "لكل إقلاع، بعد إعداد قوائم التشغيل في «الحمولات»: يشغّل قائمة بدء التشغيل (kstuff، ShadowMount+…)، ويرسل المساعد بالطريقة نفسها كالخطوة 2، ثم يشغّل قائمة التحميل التلقائي.",
changelog_description_v2: "ملاحظات الإصدار لكل نسخة من ps5upload حتى هذه النسخة، مرفقة مع التطبيق. الإصدارات الأحدث وتنزيلاتها موجودة على GitHub.",
cheats_reapply: "إعادة التطبيق على اللعبة الجارية",
