cheats_search_hint_v2: "أدخل اسم لعبة أو معرّف العنوان (مثل PPSA07631 أو CUSA00900) واضغط «بحث»",
cheats_search_placeholder_v2: "ابحث باسم اللعبة أو معرّف العنوان (مثل PPSA07631)",
