cheats_toast_reapply_no_game: "لا توجد لعبة قيد التشغيل، لذا لم يُعَد تطبيق شيء. أُعيدت قراءة ملفات الغش.",
companion_suggest_body_v2: "يعمل ps5upload مع kstuff (ثغرة النواة) و ShadowMount+ (تركيب النسخ الاحتياطية للألعاب تلقائيًا) وعشرات الحمولات المنزلية الأخرى. الحمولات → الكتالوج يرسلها بنقرة واحدة.",
companion_suggest_open_payloads: "فتح الحمولات",
connection_first_run_nudge_body_v2: "يُنزّل معالج الإعداد kstuff و ShadowMount+ ويرسلهما، ثم المساعد، بالترتيب الصحيح. إذا كان جهازك يحمّل kstuff بنفسه (محمّل تلقائي، etaHEN)، فإن الخطوة 2 أدناه ترسل المساعد فقط.",
connection_step2_which: "يرسل هذا المساعد فقط. لتحميل kstuff و ShadowMount+ أيضًا، استخدم معالج الإعداد في المرة الأولى، أو «بدء تشغيل سريع» أدناه عند كل إقلاع بعد إعداد قوائم التشغيل.",
console_snapshots: "لقطات الجهاز",
fakelibs_scan_body_all: "اجمع المكتبات من الألعاب المنقولة خلفيًا مسبقًا على كل جهاز قمت بإعداده ({consoles} جهاز). جميعها تغذّي مجموعة مشتركة واحدة.",
fakelibs_set_remove_confirm_action: "إزالة",
fakelibs_set_remove_confirm_body: "سيُحذف «{label}» من مجموعة المكتبات. تحتفظ الألعاب المنقولة خلفيًا مسبقًا بمكتباتها، لكن النقل الخلفي للعبة تحتاج هذه المجموعة سيتطلب إضافتها مجددًا.",
fakelibs_set_remove_confirm_title: "إزالة مجموعة المكتبات هذه؟",
first_run_description_v3: "يحمّل ما تحتاجه معظم الإعدادات بالترتيب الصحيح: kstuff (يتيح تثبيت الحزم المزيفة وتشغيلها)، و ShadowMount+ (يضع صور الألعاب ومجلداتها على الشاشة الرئيسية لـ PS5)، ومساعد ps5upload. بعد إعادة تشغيل PS5، تعرض شاشة الاتصال هذا المعالج مجددًا.",
