first_run_note_verified: "تم التحقق — v{version}",
first_run_note_waiting: "انتظار {n} ث قبل الحمولة التالية…",
fw_spoof_title_v2: "فحص انتحال البرنامج الثابت",
hardware_description_v2: "تُحدَّث معلومات النظام ومدة التشغيل والتخزين تلقائيًا كل 5 ثوانٍ أثناء اتصال المساعد. تُقرأ درجات الحرارة الحية وتردد المعالج عند الطلب — انقر «قراءة المستشعرات». البرنامج الثابت للبيع بالتجزئة لا يكشف كل القراءات (استخدام المعالج مثلًا)؛ وتظهر تلك كشرطة.",
health_cat_network: "الشبكة",
hw_cpu_usage_retail: "غير قابل للقراءة على البرنامج الثابت للبيع بالتجزئة",
hw_fan_confirm_msg: "سيعمل التحكم بمروحة الجهاز على الحفاظ على درجة الحرارة هذه، ويعيد ps5upload ضبطها في كل مرة يُحمَّل فيها المساعد. القيمة الأقل أعلى صوتًا؛ والأعلى تسمح للجهاز بالعمل بحرارة أكبر.",
hw_fan_confirm_title: "ضبط هدف المروحة على {c} °C؟",
