keep_ps5_awake_mode_hint_v2: "يعيد ضبط مؤقت الاستعداد التلقائي في PS5 دوريًا حتى لا يدخل وضع الراحة. «أثناء الرفع والتثبيت» يحمي عمليات الرفع الطويلة (سبب شائع لفشل الرفع؛ الافتراضي). «دائمًا أثناء الاتصال» يُبقي كل جهاز يعمل عليه المساعد خارج وضع الراحة طالما التطبيق مفتوح. يظل وضع PS5 في وضع الراحة يدويًا ممكنًا في كل الأوضاع.",
kernellog_categories_explainer: "تبدأ كل الفئات ظاهرة. فئات Sony هي الأنظمة الفرعية للجهاز نفسه، وتسجّل باستمرار على كل PS5 مكسور الحماية أيًّا كانت الحمولة العاملة؛ وليست ناتجة عن ps5upload. ألغِ تحديدها لتقليل الضوضاء.",
payloads_cached_body: "نُزّل {kb} KB إلى ذاكرة التخزين المؤقت المحلية.",
payloads_cached_title: "تم تخزين {id} {tag} مؤقتًا",
payloads_description_catalog_v2: "حمولات PS5 منزلية منتقاة من جهات خارجية. تحقّق من أحدث إصدار، ونزّله مرة واحدة، ثم أرسله إلى PS5 بنقرة واحدة. تُخزَّن الإصدارات محليًا لتتمكن أيضًا من وضعها على ذاكرة USB للحمولات.",
payloads_description_send_v2: "أرسل أي ملف حمولة PS5 — .elf أو .bin أو .js أو .lua أو .jar (kstuff، مُحمِّلات منزلية مخصصة، ثغرات مرحلة المتصفح، سكربتات الإضافات، ملفات BD-JB JAR) — إلى PS5. نفس خطوات شاشة الاتصال، لكن مع ملف تختاره. يتبع المنفذ نوع الملف (.elf/.bin 9021، .jar 9025، .lua 9026، .js 50000)؛ غيّره فقط إذا كان المُحمِّل يستمع على منفذ آخر.",
payloads_download_failed: "فشل التنزيل: {id}",
payloads_open_usb_wizard_v2: "إنشاء ذاكرة USB للحمولات",
payloads_send_failed: "فشل الإرسال: {id}",
payload_refused_install: "يوجد تثبيت قيد التشغيل على PS5 هذا. أرسل هذا عند انتهائه.",
payload_refused_helper: "يوجد نقل أو عملية ملفات قيد التشغيل على PS5 هذا، وإرسال المساعد سيوقفها. أرسله عند انتهائها.",
payload_refused_loader: "مُحمّل الحمولات في PS5 مشغول. حاول مرة أخرى بعد لحظة.",
payloads_sent_body: "أُرسلت الحمولة v{version} إلى المُحمِّل على :9021. تحقّق من الإشعار على PS5.",
payloads_sent_body_pm: "لم يستجب المنفذ 9021، لذا شُغّلت الحمولة v{version} عبر Payload Manager (:8084) بدلًا من ذلك. تحقّق من الإشعار على PS5.",
payloads_sent_title: "أُرسل {id} → {host}",
peripheral_drive_attachable: "لا يحتوي هذا الطراز على محرك أقراص مدمج؛ لا تعمل هذه إلا عند توصيل المحرك الإضافي.",
power_telemetry_title_v2: "عدّادات مدى الحياة",
processes_kill_payload_body: "يُنهي هذا الحمولة «{name}» (kstuff و etaHEN وما شابه). يتوقف كل ما توفّره حتى ترسلها مجددًا، وقد تتوقف الألعاب التي تحتاجها عن العمل.",
processes_kill_payload_title: "إيقاف الحمولة «{name}»؟",
"profile.np.browser_v2": "يتطلب تسجيل الدخول تطبيق سطح المكتب: فهو يجلب np-fake-signin ويرسله إلى PS5، وهو ما لا تستطيعه واجهة الويب.",
ps5notif_empty_hint_v2: "عندما يعرض ps5upload رسالة على التلفاز، مثل رمز PIN للعب عن بُعد أو تفعيل كود غش، تُدرج هنا لتتمكن من قراءتها مجددًا. هذه ليست لوحة إشعارات PS5 نفسها؛ فالجهاز لا يسمح لنا بقراءتها.",
reset_confirm_body_browser: "يمسح هذا كل الإعدادات والحالة المحفوظة التي يحتفظ بها هذا المتصفح لـ PS5Upload، وتُعاد تحميل الصفحة من جديد. لا تُمس بيانات المحرك على الخادم (إقرانات الأجهزة، المجموعة، الخوادم المحفوظة، مكتبات النقل الخلفي، سجل التثبيت، السجلات)، ولا أي شيء على PS5. لا يمكن التراجع عن هذا.",
reset_confirm_body_v2: "يحذف هذا نهائيًا جميع بيانات PS5Upload المحلية: الإعدادات، وأجهزة PS5 المحفوظة وإقراناتها، والمجموعة، والخوادم المحفوظة وكلمات مرورها، ومكتبات النقل الخلفي، وسجل التثبيت، والمهام والأحداث، وسجل النشاط/قائمة الانتظار، والسجلات، وذاكرة الحمولات المؤقتة، وتقارير الأعطال. لا يمس أي شيء على PS5. يُعاد تحميل التطبيق بحالة جديدة. لا يمكن التراجع عن هذا.",
reset_hint_browser: "امسح كل الإعدادات والحالة المحفوظة التي يحتفظ بها هذا المتصفح لـ PS5Upload وابدأ من جديد. ما يحتفظ به المحرك على خادمه (إقرانات الأجهزة، المجموعة، الخوادم المحفوظة، مكتبات النقل الخلفي، سجل التثبيت، السجلات) لا يُمس، ولا يتأثر أي شيء على PS5.",
reset_hint_v2: "امحُ كل أثر محلي لـ PS5Upload وابدأ من جديد: الإعدادات، وأجهزة PS5 المحفوظة وإقراناتها، والمجموعة، والخوادم المحفوظة وكلمات مرورها، ومكتبات النقل الخلفي، وسجل التثبيت، والمهام والأحداث، وسجل النشاط/قائمة الانتظار، والسجلات، وذاكرة الحمولات المؤقتة، وتقارير الأعطال. لا يتأثر أي شيء على PS5. النسخ الاحتياطي / الاستعادة أعلاه لا يشمل الإقرانات أو المجموعة أو كلمات مرور الخوادم أو مكتبات النقل الخلفي.",
saves_backup_usb_tooltip_v2: "اضغط بيانات الحفظ هذه في ملف zip على القرص في مسار الحفظ المحدد في الإعدادات (قرص USB على PS5). تُنسخ إلى هذا الكمبيوتر وتُضغط وتُعاد، لذا أبقِ التطبيق مفتوحًا؛ وتُحذف النسخة هنا بعد ذلك.",
saves_description_browser: "بيانات الحفظ على PS5، إدخال واحد لكل لعبة. يتطلب نسخ بيانات الحفظ احتياطيًا إلى .zip واستعادتها تطبيق سطح المكتب؛ هنا يمكنك رؤيتها وفتح مجلداتها.",
saves_restore_usb_tooltip_v2: "استعد بيانات الحفظ هذه من أحدث نسخة احتياطية لها في مسار الحفظ المحدد في الإعدادات. يُنسخ ملف zip إلى هذا الكمبيوتر ويُفك ضغطه ويُعاد إلى PS5، لذا أبقِ التطبيق مفتوحًا. يستبدل بيانات الحفظ الحالية.",
