servers_subtitle: "أجهزة NAS والخوادم الخاصة بك (SMB، FTP، FTPS، SFTP/WebDAV). أينما تتصفح بحثًا عن لعبة أو ملف، اختر منها عبر ▾ بجوار «استعراض».",
settings_artwork_cache_explain_v2: "تُحفظ أغلفة الألعاب حيث يعمل المحرك (هذا الكمبيوتر، أو الخادم في نسخة الويب) لتُحمَّل فورًا بدلًا من قراءتها من PS5 في كل مرة. تُحدَّث تلقائيًا، وتُزال لجهاز ما عند تثبيت لعبة أو إلغاء تثبيتها عليه.",
settings_backup_downloaded: "تم تنزيل {name}",
settings_backup_no_pairing: "لا يتضمن هذا الملف إقران Remote Play ومفاتيح التنبيه. على جهاز جديد، أقرن الجهاز مجددًا.",
settings_backup_hint_v2: "اجمع السمة وقائمة أجهزة PS5 وسجل الإشعارات وسجل النشاط وتفضيلات أخرى في ملف JSON واحد، لاستعادتها بعد مسح تخزين التطبيق أو على جهاز آخر. لا تُضمَّن إقرانات الأجهزة والمجموعة وكلمات مرور الخوادم المحفوظة ومكتبات النقل الخلفي.",
