settings_card_console_rest: "وضع الراحة",
settings_card_console_connect: "الاتصال",
auto_bringup_label: "التشغيل تلقائيًا",
auto_bringup_hint: "عندما يكون المُحمّل (elfldr، المنفذ 9021) على جهاز PS5 محفوظ يعمل والمساعد لا يعمل، يشغّل التطبيق بدء التشغيل السريع بنفسه: قائمة تشغيل بدء التشغيل إن حددتها، ثم المساعد، ثم قائمة تشغيل المُحمّل التلقائي. مرة واحدة في كل مرة يبدأ فيها الجهاز؛ وبعد وضع الراحة يُرسل المساعد فقط من جديد. ينتظر نحو 90 ثانية بعد ظهور المُحمّل حتى ينتهي المُحمّل التلقائي الخاص بالجهاز أولًا. معطّل افتراضيًا.",
bringup_auto_hint_short: "يشغّل هذا بنفسه عندما يعمل مُحمّل PS5 ولا يعمل المساعد، بعد نحو 90 ثانية من ظهور المُحمّل. مرة واحدة في كل مرة يبدأ فيها الجهاز.",
settings_card_install_fallback: "عندما يتعذّر على PS5 جلب حزمة",
settings_card_system_files: "ملفات النظام",
settings_file_hint_v2: "تُنسخ التفضيلات الرئيسية (السمة، اللغة، المحرك، مسار الحفظ، إعدادات الرفع الافتراضية، إمكانية الوصول، الشريط الجانبي) إلى ملف JSON هذا. يمكنك تعديله يدويًا؛ وتسري التعديلات عند تشغيل التطبيق في المرة التالية. لا يحتوي على كل شيء: استخدم النسخ الاحتياطي / الاستعادة لنقل جميع تفضيلاتك.",
