"rpg_service_body": "الإعدادات › النظام › اللعب عن بُعد › تفعيل اللعب عن بُعد. يمكن للتطبيق تشغيله لك، كما يمكنه على البرنامج الثابت 10.00 وما بعده السماح به لهذا المستخدم أيضًا. إن ظهر بعدها عند «ابدأ» أن Remote Play مُعطّل، ففعّله من إعدادات PS5 نفسها: المفتاح الذي يُعتدّ به هو مفتاح الجهاز.",
