"rp_picture_here_hint": "عند إيقافه، تبدأ البثوث الجديدة بلا صورة أو صوت أو يد تحكم هنا، ما يوفّر معالج هذا الجهاز وبطاريته. يبقى البث متاحًا للأصدقاء في Play Together وللبث المباشر، ويمكنك تشغيله من البث في أي وقت.",
