"golive_picture_hint": "عند إيقافه، يمرر هذا الكمبيوتر البث دون فك ترميزه أو عرضه، ما يقلل استهلاك المعالج والحرارة. أبقِ التطبيق يعمل؛ يبقى التحكم هنا.",
"pt_picture_hint": "عند إيقافه، يكتفي هذا الجهاز بدعوة أصدقائك: لا صورة أو صوت أو يد تحكم هنا، وتستمر لعبة أصدقائك. مناسب للعب على التلفزيون.",
"pt_tv_title": "هل تلعب على التلفزيون؟",
"pt_tv_note": "هذا البث مسجَّل الدخول بمستخدم PS5 الذي أقرنته مع PS5Upload. اضغط PS على يد DualSense المتصلة بالجهاز واختر مستخدمًا آخر: هذا أنت على التلفزيون. اختيار مستخدم البث نفسه ينهي البث للجميع، بمن فيهم الأصدقاء. تحسب بعض الألعاب مستخدم البث لاعبًا أيضًا، ما قد يترك مكانًا أقل لصديق.",
"pt_tv_seats": "يقبل PS5 أربع وحدات تحكم. عند استخدام DualSense على التلفاز، يستخدم أول صديق وحدة تحكم البث نفسها ويلعب بمستخدمها دون اختيار مستخدم، ويحصل صديقان آخران على وحدة تحكم خاصة بكل منهما: يتسع ذلك لثلاثة أصدقاء.",
"pt_stream_seat_note": "يستخدم صديق وحدة تحكم هذا البث، لذا لن تعمل وحدة التحكم لديك هنا حتى يغادر.",
"queue_waiting_for_engine_queue": "في الانتظار: يستخدم برنامج نصي أو وكيل جهاز PS5 هذا عبر قائمة انتظار المحرك. يتابع هذا العنصر تلقائيًا بعد ذلك.",
