"send_title_v2": "الرفع والتثبيت",
"collection.send_many_body_v2": "يحصل كل PS5 على ما ينقصه: حزمة اللعبة، أو مجلدها أو صورتها أو أرشيفها، إضافةً إلى التحديثات الأحدث ومحتوى DLC للألعاب التي لديه. تُبث الحزم من هذا الحاسوب؛ ويُرفع الباقي إلى محرك الأقراص المحدد في «الرفع والتثبيت»، داخل مجلد homebrew.",
"first_run_step4_body_v3": "أدخل ذاكرة USB تحتوي على صور ألعاب .ffpkg في جهاز PS5 وسيركّبها ShadowMount+ تلقائيًا — ستظهر في «الألعاب». لإرسال ملفات أخرى أو تثبيت حزم .pkg، استخدم «الرفع والتثبيت».",
"first_run_go_upload_v2": "افتح «الرفع والتثبيت»",
"fpkg.aboutFake_v2": "الناتج حزمة مزيفة، لذا يحتاج الجهاز إلى تحميل دعم الحزم المزيفة قبل تثبيتها: kstuff (الإصدار الذي يدعم حزم PS5 المزيفة) وa53_ppr_install_fast.elf وshadowmountplus.elf، بهذا الترتيب. تذكر صفحة «الرفع والتثبيت» الأمر نفسه بجوار أزرار التثبيت.",
"fpkg.openUpload_v2": "افتح «الرفع والتثبيت»",
"connection_step3_hint_v3": "افتح «الرفع والتثبيت» وأفلت مجلد لعبة أو صورة .exfat أو .ffpkg أو حزمة .pkg. تظهر الصور والمجلدات التي ترسلها في صفحة اللعبة ضمن «الألعاب»، حيث يضعها «تثبيت» على الشاشة الرئيسية لـ PS5.",
"connection_go_upload_v2": "افتح «الرفع والتثبيت»",
"netdoctor.speed_cap.on.fix_v2": "أزل الحد في «الرفع والتثبيت» إن لم تكن بحاجة إليه.",
"payloads_fpkg_ppr_note_v2": "يحتاج تثبيت الحزم المزيفة أيضًا إلى a53_ppr_install_fast.elf، وهو غير موجود في هذه القائمة: لا يوجد تنزيل منشور له، ويُبنى من الشيفرة المصدرية على GitHub. تسرد «الرفع والتثبيت» كل ما تحتاجه الحزم المزيفة بالترتيب.",
"fs_extract_next_pkgs_v2": "يحتوي على {n} حزمة: ثبّتها من «الرفع والتثبيت»، أو من صفها هنا.",
"game_hub_no_addons_v2": "لا توجد حزم DLC مجهّزة لهذا العنوان. أرسل واحدة من «الرفع والتثبيت».",
"game_hub_open_install_v2": "افتح «الرفع والتثبيت»",
"bandwidth_cap_off_hint_v3": "بلا حد. اضبط واحدًا إن كانت عمليات الرفع تُشبع شبكة Wi-Fi/LAN وتبطئ الأجهزة الأخرى. ينطبق على كل رفع، من «الرفع والتثبيت» والقائمة و«الملفات»، بدءًا من الرفع التالي.",
"game_hub_no_updates_v2": "لا توجد حزم تحديث مجهّزة لهذا العنوان. أرسل واحدة من «الرفع والتثبيت».",
"pkglib.fpkgsupport.firmware": "حزم PS5 المزيفة (PS5 FPKG) غير مدعومة بعد على البرامج الثابتة الأحدث من 11.60: تُثبَّت، لكن اللعبة لا تعمل. حزم PS4 المزيفة تعمل بلا مشكلة.",
"upload_drop_here3": "أفلت أو اختر حزمًا أو ألعابًا أو صور أقراص أو أرشيفات أو أي ملف",
"upload_pick_here_mobile3": "اختر حزمًا أو ألعابًا أو صور أقراص أو أرشيفات أو أي ملف",
"upload_drop_kind_pkg": "الحزم (.pkg و.fpkg): تُثبَّت كلعبة أو تحديث أو DLC، تُبث من هنا أو تُرفع أولًا.",
"upload_drop_kind_game": "مجلدات الألعاب وتفريغاتها: تُنسخ إلى PS5؛ ويمكن وضعها على الشاشة الرئيسية.",
"upload_drop_kind_image": "صور الأقراص (.exfat و.ffpkg و.ffpfs و.ffpfsc): تُنسخ إلى PS5؛ ويمكن تركيبها.",
"upload_drop_kind_archive": "الأرشيفات (.zip و.7z و.rar): تُفك على PS5 أو تُرسل كما هي — أنت تختار.",
"upload_drop_kind_other": "أي ملف أو مجلد آخر: يُنسخ كما هو.",
"upload_other_ways": "أو ثبّت حزمة:",
"queue_stream_fail_hint": "يجعل «بث وتثبيت» جهاز PS5 يجلب الحزمة من هذا الحاسوب. إذا استمر الفشل، فاسمح لـ ps5upload عبر جدار حماية هذا الحاسوب على الشبكة المحلية كي يصل إليه PS5، أو استخدم «إعادة المحاولة عبر الرفع» الذي ينسخ الحزمة إلى PS5 أولًا ثم يثبّتها.",
"err_install_enoent_generic_v2": "تعذّر على مُثبِّت Sony فتح ملف يحتاجه أثناء التثبيت (خطأ النواة 0x80020002 = ENOENT). إذا كانت هذه حزمة DLC، فإن اللعبة الأساسية غير مثبَّتة بعد — ثبّت الأساسية أولًا. وإلا فربما حُذفت الحزمة المُجهَّزة بين الرفع والتثبيت؛ أعد محاولة التثبيت مرة واحدة. إذا استمر الفشل، فثبّتها باستخدام «بث وتثبيت» في «الرفع والتثبيت»، الذي يرسل الحزمة مباشرة من هذا الحاسوب بدلًا من نسخها إلى الجهاز أولًا.",
"err_display_crashed": "واجهت شاشة التطبيق خطأً أثناء هذا (React #185) وتوقفت عن متابعة النقل، وقد يكون انتهى على أي حال. تحقّق من PS5 أو اضغط إعادة المحاولة. إرسال تقرير خطأ الآن يساعدنا في إصلاحه.",
"upload_convert_first": "التحويل أولًا",
"batch_convert_first_hint": "افتح الألعاب والمجلدات والصور المحددة في الورشة، لتصنع منها حزمًا أو صورًا أو مجلدات أولًا",
"add_sources_pick_folders": "اختر مجلدًا أو أكثر",
"add_sources_pick_files": "اختر ملفًا أو أكثر",
"workshop_add_hint": "اختر لعبة واحدة لفحصها هنا. تدخل عدة ألعاب، أو مجلد ألعاب، قائمة الانتظار وتُصنع واحدة تلو الأخرى.",
"cq_title_v2": "⑤ قائمة الانتظار",
"cq_about": "تُصنع واحدة تلو الأخرى على هذا الحاسوب، كلٌّ وفق إعدادات ② و③ و④ عند إضافتها. أضف المزيد في ①، حتى أثناء تشغيل القائمة؛ وغيّر لعبة تنتظر بزر الخيارات الخاص بها.",
"cq_then_send": "اللعبة المعدّة للتثبيت أو الرفع تنتقل إلى قائمة انتظار {send} بعد صنعها.",
"cq_open_send": "افتح {send}",
"backup_alike_toggle": "{count} نسخ متشابهة منذ {since}. اعرض كل نسخة لاستعادة نسخة أقدم.",
"add_sources_no_picker": "لا يمكن لهذا الإصدار تصفح هذا الجهاز — اكتب مسارًا يمكن للمحرك رؤيته.",
"collection.empty_body_v2": "يتم العثور على الحزم ومجلدات الألعاب وصور الألعاب والأرشيفات الموجودة بداخله وتجميعها حسب اللعبة. لا يتغير شيء في المجلد. يصلح مجلد على هذا الجهاز أو محرك خارجي أو مجلد على NAS أو خادم (SMB وFTP وSFTP وWebDAV).",
