"queue_added_waits_for_start_body": "خيار «بدء قائمة الانتظار عند إضافة شيء» متوقف، لذا لن يبدأ شيء حتى تضغط «بدء قائمة الانتظار».",
"queue_auto_start": "بدء قائمة الانتظار عند إضافة شيء",
"queue_auto_start_tooltip": "تشغيل: «تثبيت» و«الرفع الآن» و«إرسال» تبدأ قائمة انتظار هذا الجهاز كاملة بالترتيب. إيقاف: تضيف إلى قائمة الانتظار فقط، ولا يعمل شيء حتى تضغط «بدء قائمة الانتظار».",
"queue_auto_start_hint": "تشغيل: «تثبيت» و«الرفع الآن» و«إرسال» تبدأ قائمة انتظار الجهاز كاملة بالترتيب — لا ما أضفته للتو فقط. إيقاف: تضيف إلى قائمة الانتظار فقط، ولا يعمل شيء حتى تضغط «بدء قائمة الانتظار». مُفعّل افتراضيًا.",
"queue_start_rest_tooltip": "العناصر التي بدأتها فقط هي التي تعمل. هذا يشغّل أيضًا كل ما ينتظر، بترتيب قائمة الانتظار.",
